#!/usr/bin/env node
/**
 * Refresh the copy of the payload that ships inside the app.
 *
 * The app has three sources of data, in order: the assets written here, the last
 * good download cached on the device, and the network. The assets are what make
 * a first launch work in a tunnel, so they need to exist — but they must NOT be
 * regenerated by the nightly scrape. If they were, every night's data commit
 * would carry ~800 KB of asset churn and trigger a mobile CI build for data the
 * running app fetches over HTTP anyway.
 *
 * So this is deliberately manual: run it when cutting a release, so the shipped
 * seed is roughly current, and let the nightly job leave `mobile/` alone.
 *
 *   npm run build-mobile-payload && npm run sync-mobile-seed
 *
 * Both files are gzipped because the store's number is download size; Dart reads
 * them back with `gzip.decode`.
 */
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const ASSETS = [
  {
    from: "public/data/published/mobile-v1.json",
    to: "mobile/assets/seed-v1.json.gz",
    hint: "npm run build-mobile-payload",
  },
];

const kb = (n) => `${(n / 1024).toFixed(0)} KB`;

let total = 0;
for (const { from, to, hint } of ASSETS) {
  const source = path.join(ROOT, from);
  if (!fs.existsSync(source)) {
    console.error(`[mobile-seed] ${from} is missing — run \`${hint}\` first.`);
    process.exit(1);
  }
  const raw = fs.readFileSync(source);
  const packed = zlib.gzipSync(raw, { level: 9 });
  const target = path.join(ROOT, to);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, packed);
  total += packed.length;
  console.log(
    `[mobile-seed] ${from} → ${to}  ${kb(raw.length)} → ${kb(packed.length)}`,
  );
}
console.log(`[mobile-seed] bundled assets total ${kb(total)}`);
